<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\DcrInitialAccessToken\Domain\ValueObject\Holder\DcrInitialAccessTokenAllowedGrantTypesAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the DcrInitialAccessTokenAllowedGrantTypesAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class DcrInitialAccessTokenAllowedGrantTypesAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getAllowedGrantTypes returns null on a freshly created holder.
     */
    public function testAllowedGrantTypesNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithDcrInitialAccessTokenAllowedGrantTypesAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isAllowedGrantTypesAssigned());
        $this->assertNull($holder->getAllowedGrantTypes());
    }
}
class ImplWithDcrInitialAccessTokenAllowedGrantTypesAttributeHolderUnitTest
{
    use DcrInitialAccessTokenAllowedGrantTypesAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedAllowedGrantTypesRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultAllowedGrantTypes();
    }
}
